import type { NutrientKey } from './types';

/**
 * Contenu explicatif de chaque nutriment, affiché dans le dépliant de l'onglet
 * « Nutriments ». Complète `RDA` : les CHIFFRES (ajr, optimal, upper, toxic)
 * vivent dans `rda.ts`, les EXPLICATIONS ici — sinon `rda.ts` deviendrait
 * illisible sous le texte.
 *
 * Chaque nutriment répond aux quatre mêmes questions, toujours dans cet ordre,
 * et toujours avec des quantités :
 *
 *  1. `low`    — sous quelle dose ça devient un problème, et lequel exactement ;
 *  2. `role`   — ce que la molécule fait dans le corps ;
 *  3. `higher` — ce qu'on gagne à monter au-dessus de l'AJR… ou rien du tout ;
 *  4. `high`   — à partir de quelle dose ça devient risqué, à quelle dose les
 *                dégâts ont réellement été observés, et lesquels.
 *
 * Les seuils cités sont ceux de l'adulte (références EFSA/ANSES, et IOM quand
 * l'Europe ne fixe rien). Les doses de danger sont celles des cas documentés,
 * pas des extrapolations : quand rien n'est établi, `high` le dit plutôt que
 * d'inventer une limite.
 */

/**
 * Solidité de ce qui est affirmé pour un nutriment. Affiché EN TÊTE du dépliant,
 * avant le contenu : savoir si on lit un fait établi ou un pari raisonnable
 * change la façon de lire ce qui suit.
 *
 *  - `etabli`    : carence historiquement décrite, mécanisme connu, seuils
 *                  officiels concordants (EFSA/ANSES/IOM) ;
 *  - `discute`   : le plancher est solide, mais la cible haute ou le seuil de
 *                  danger reposent sur des cohortes d'observation, des essais
 *                  contradictoires, ou une extrapolation ;
 *  - `incertain` : pas de référence officielle du tout — le repère a été
 *                  construit, il vaut ce que vaut son raisonnement.
 */
export type EvidenceLevel = 'etabli' | 'discute' | 'incertain';

export interface Evidence {
  level: EvidenceLevel;
  /** Ce qui est solide, ce qui ne l'est pas, et POURQUOI le doute subsiste. */
  text: string;
}

export const EVIDENCE_LABEL: Record<EvidenceLevel, string> = {
  etabli: 'Bien établi',
  discute: 'Partiellement discuté',
  incertain: 'Repère incertain',
};

export interface NutrientGuide {
  /** Ce qu'on sait vraiment — et ce dont on doute — sur les chiffres ci-dessous. */
  evidence: Evidence;
  /** Trop bas : le seuil chiffré et ce qui se passe en dessous. */
  low: string;
  /** À quoi ça sert — le rôle développé (la version courte est dans `RdaEntry.role`). */
  role: string;
  /** Ce qu'on gagne à dépasser l'AJR jusqu'à l'optimal — y compris « rien ». */
  higher: string;
  /** Trop haut : seuil de prudence, dose des effets observés, nature du danger. */
  high?: string;
  /** Cas particuliers développés (fer selon la personne, familles d'AG saturés…). */
  extra?: { title: string; text: string }[];
  /** « À retenir » : la nuance pratique qui change quelque chose au quotidien. */
  tip?: string;
}

